#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, saving;
    scanf("%d %d", &n, &saving);
    vector<long long> a(n), b(n);
    for (auto &x : a) scanf("%lld", &x);
    for (auto &x : b) scanf("%lld", &x);
    // 0/1 knapsack: cost = current price, value = future - current.
    vector<long long> dp(saving + 1, 0);
    for (int i = 0; i < n; i++) {
        long long cost = a[i], gain = b[i] - a[i];
        if (gain <= 0 || cost > saving) continue;
        for (long long money = saving; money >= cost; money--)
            dp[money] = max(dp[money], dp[money - cost] + gain);
    }
    printf("%lld\n", dp[saving]);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), saving = nextInt();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) b[i] = nextLong();
        // 0/1 knapsack: cost = current price, value = future - current.
        long[] dp = new long[saving + 1];
        for (int i = 0; i < n; i++) {
            long cost = a[i], gain = b[i] - a[i];
            if (gain <= 0 || cost > saving) continue;
            int c = (int) cost;
            for (int money = saving; money >= c; money--)
                dp[money] = Math.max(dp[money], dp[money - c] + gain);
        }
        System.out.println(dp[saving]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, saving := readInt(), readInt()
	a, b := make([]int, n), make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	for i := range b {
		b[i] = readInt()
	}
	// 0/1 knapsack: cost = current price, value = future - current.
	dp := make([]int, saving+1)
	for i := 0; i < n; i++ {
		cost, gain := a[i], b[i]-a[i]
		if gain <= 0 || cost > saving {
			continue
		}
		for money := saving; money >= cost; money-- {
			if v := dp[money-cost] + gain; v > dp[money] {
				dp[money] = v
			}
		}
	}
	fmt.Println(dp[saving])
}
